from collections import Counter
def M(n): return Counter(str(n))
def Dset(n): return set(str(n))
def classify(v, x, y):
    if v != x*y: return 'not a product'
    if M(v) == M(x) + M(y): return 'vampire'
    shared = len(Dset(v) & (Dset(x) | Dset(y)))
    if shared == 0: return 'ghost'
    if shared == 1: return 'werewolf'
    return 'ordinary'
print(classify(1260, 21, 60))
ghost, total = Counter(), Counter()
for x in range(10,100):
    for y in range(x,100):
        v = x*y; total[len(str(v))] += 1
        if classify(v,x,y) == 'ghost': ghost[len(str(v))] += 1
for Ln in sorted(total):
    print(Ln, round(ghost[Ln]/total[Ln], 4))

